insert into public.categories (id, slug, name, description, sort) values
  ('11111111-1111-4111-8111-111111111111', 'school-uniforms', 'School Uniforms', 'Primary, high school, international, and preschool kits — polos, shirts, trousers, skirts, and blazers.', 1),
  ('22222222-2222-4222-8222-222222222222', 'sports', 'Sports & PE', 'House tees, jerseys, and dry-fit kits for matches and PE.', 2),
