  ('44444444-4444-4444-8444-444444444444', 'accessories', 'Accessories', 'Ties, caps, bags, socks, belts, and ID lanyards.', 4);

insert into public.products (id, slug, name, description, category_id, price, compare_at, hero_image, gallery, specs, featured) values
  ('a0000001-0000-4000-8000-000000000001', 'polo-tshirt', 'School Polo T-Shirt',
    'Greenfield Academy polo in navy cotton pique (220 GSM) with sky-blue collar tipping and an embroidered school crest. Breathable, moisture-wicking, and built for everyday wear from primary through senior secondary.',
    '11111111-1111-4111-8111-111111111111', 890, null, '/products/polo.png',
    '["/products/polo.png"]'::jsonb,
    '{"Fabric":"Cotton pique 220 GSM","Branding":"Embroidery, screen print, heat transfer","Features":"Breathable, moisture-wicking, shape retention","Sample":"Greenfield Academy"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000002', 'formal-shirt', 'Formal School Shirt',
    'Crisp poplin formal shirt with chest embroidery and woven neck labels. Easy-iron, breathable, and tailored for assemblies and school days that need a smarter look.',
    '11111111-1111-4111-8111-111111111111', 1190, null, '/products/shirt.png',
    '["/products/shirt.png"]'::jsonb,
    '{"Fabric":"Poplin / oxford / poly-cotton","Branding":"Chest embroidery, woven labels, name embroidery","Features":"Crisp appearance, easy iron, durable"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000003', 'school-trousers', 'School Trousers',
    'Wrinkle-resistant poly-viscose trousers with a comfortable school fit, custom buttons, and embroidered branding options. Built to hold shape through the term.',
    '11111111-1111-4111-8111-111111111111', 1490, null, '/products/trousers.png',
    '["/products/trousers.png"]'::jsonb,
    '{"Fabric":"Poly viscose / cotton twill / stretch twill","Branding":"Woven labels, embroidered logo, custom buttons","Features":"Wrinkle resistant, durable, shape retention"}'::jsonb, false),
  ('a0000001-0000-4000-8000-000000000004', 'school-skirt', 'School Skirt',
    'Poly-viscose skirt with excellent drape, wrinkle resistance, and an optional embroidered crest. Custom waistband labels available for house or school identity.',
    '11111111-1111-4111-8111-111111111111', 1290, null, '/products/skirt.png',
    '["/products/skirt.png"]'::jsonb,
    '{"Fabric":"Poly viscose / polyester / stretch blend","Branding":"Woven labels, embroidered crest","Features":"Excellent drape, wrinkle resistant"}'::jsonb, false),
  ('a0000001-0000-4000-8000-000000000005', 'school-blazer', 'School Blazer',
    'Structured navy blazer in premium poly-viscose suiting, with embroidered crest, metal buttons, satin labels, and a smooth inner lining. The formal piece of a complete school kit.',
    '11111111-1111-4111-8111-111111111111', 3490, null, '/products/blazer.png',
    '["/products/blazer.png"]'::jsonb,
    '{"Fabric":"Polyester viscose / wool blend / premium suiting","Branding":"Embroidered crest, woven labels, metal buttons","Features":"Structured look, premium finish, long-lasting"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000006', 'school-sweater', 'School Sweater',
    'Warm, lightweight knit sweater in acrylic-cotton or merino blend. Knit-in or embroidered school logo, designed for winter assemblies without the bulk.',
    '11111111-1111-4111-8111-111111111111', 1690, null, '/products/sweater.png',
    '["/products/sweater.png"]'::jsonb,
    '{"Fabric":"Acrylic cotton knit / wool blend / merino","Branding":"Knit logo, embroidery, woven labels","Features":"Warm, lightweight, soft, durable"}'::jsonb, false),
  ('a0000001-0000-4000-8000-000000000007', 'school-hoodie', 'School Hoodie',
    'Navy cotton-fleece hoodie with embroidered crest, puff-print sleeve branding, and ribbed cuffs. Warm enough for winter, easy enough for everyday campus wear.',
    '11111111-1111-4111-8111-111111111111', 1890, 2190, '/products/hoodie.png',
    '["/products/hoodie.png"]'::jsonb,
    '{"Fabric":"Cotton fleece / poly-cotton fleece / French terry","Branding":"Embroidery, puff print, DTF, heat transfer","Features":"Warm, breathable, kangaroo pocket"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000008', 'house-tshirt', 'House T-Shirt',
    'Colour-coded house tee in polyester dry-fit with embroidered crest and contrast shoulder piping. Built for sports days, events, and house activities.',
    '22222222-2222-4222-8222-222222222222', 690, null, '/products/house-tee.png',
    '["/products/house-tee.png"]'::jsonb,
    '{"Fabric":"Polyester dry-fit / cotton jersey / poly-cotton","Branding":"Sublimation, embroidery, screen print","Features":"Colour coding, breathable, lightweight"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000009', 'sports-uniform', 'Sports Uniform Kit',
    'Navy-and-white micro-polyester PE kit with heat-transfer crest, vinyl numbers, and contrast side panels. Moisture-wicking, quick-dry, and stretchable for all school sports.',
    '22222222-2222-4222-8222-222222222222', 2190, null, '/products/sports.png',
    '["/products/sports.png"]'::jsonb,
    '{"Fabric":"Micro polyester / dry-fit / mesh / spandex blend","Branding":"Heat transfer, sublimation, vinyl numbers","Features":"Moisture-wicking, quick dry, lightweight, stretchable"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000010', 'club-tshirt', 'College Club T-Shirt',
    'Premium sports-inspired college tee in dark forest green with white ringer collar and cuffs. Varsity chest lettering, official crest, and textured polyester jersey — as shown for XYZ College in the Slyde catalogue.',
    '33333333-3333-4333-8333-333333333333', 990, null, '/products/club-tee.png',
    '["/products/club-tee.png"]'::jsonb,
    '{"Fabric":"Textured polyester jersey","Color":"Dark forest green with white cuffs","Fit":"Athletic, football-jersey inspired"}'::jsonb, true),
  ('a0000001-0000-4000-8000-000000000011', 'performance-tee', 'Performance Round-Neck Tee',
    'Sublimated round-neck sports tee with championship numbering and a breathable athletic cut. Shown in the catalogue as SM Sportswear — ready to rebrand for any school team.',
    '22222222-2222-4222-8222-222222222222', 850, null, '/products/jersey-tee.png',
    '["/products/jersey-tee.png"]'::jsonb,
    '{"Fabric":"Performance polyester","Branding":"Sublimation, heat transfer","Features":"Lightweight, breathable, full-colour print"}'::jsonb, false),
  ('a0000001-0000-4000-8000-000000000012', 'school-tie', 'School Tie',
    'Polyester-satin school tie with wrinkle-resistant, colourfast finish. Woven logo, embroidery, or jacquard weaving for house stripes and crests.',
    '44444444-4444-4444-8444-444444444444', 490, null, '/products/tie.png',
    '["/products/tie.png"]'::jsonb,
    '{"Fabric":"Polyester satin / microfiber / silk blend","Branding":"Woven logo, embroidery, jacquard","Features":"Elegant finish, wrinkle resistant, colourfast"}'::jsonb, false),
  ('a0000001-0000-4000-8000-000000000013', 'school-cap', 'School Cap',
    'Cotton-twill school cap with 3D or flat embroidery. Breathable, durable, and ready for crests, house colours, or sports-day marks.',
    '44444444-4444-4444-8444-444444444444', 590, null, '/products/cap.png',
    '["/products/cap.png"]'::jsonb,
    '{"Fabric":"Cotton twill / brushed cotton / polyester microfiber","Branding":"3D embroidery, screen print, woven patch","Features":"Comfortable, breathable, durable"}'::jsonb, false),
  ('a0000001-0000-4000-8000-000000000014', 'school-bag', 'School Bag',
    '600D / 1000D polyester school bag — water-resistant, tear-resistant, and light enough for daily commute. Crest, rubber patch, or reflective print available.',
    '44444444-4444-4444-8444-444444444444', 1590, null, '/products/bag.png',
    '["/products/bag.png"]'::jsonb,
    '{"Fabric":"600D / 1000D polyester / nylon ripstop","Branding":"Embroidery, rubber patch, reflective print","Features":"Water resistant, tear resistant, lightweight"}'::jsonb, false);

